// Native textarea focus may expose its caret while leaving most of the
// field behind the sticky header. Keep the focused control visible.
document.addEventListener("focusin", (event) => {
	const target = event.target;
	if (!(target instanceof HTMLElement)) return;
	requestAnimationFrame(() => {
		if (document.activeElement !== target || !target.matches(":focus-visible") || target.getClientRects().length === 0) return;
		const header = document.querySelector(".hw-head[data-pin]");
		if (!header || header.contains(target) || getComputedStyle(header).position !== "sticky") return;
		const top = target.getBoundingClientRect().top;
		const clear = header.getBoundingClientRect().bottom + 8;
		if (top < clear) window.scrollBy(0, top - clear);
	});
});

